use std::hash::poseidon2_permutation;

// Poseidon2 sponge hash matching bb.js / Noir stdlib internals
// Rate = 3, Capacity = 1, IV = message_len * 2^64 in state[3]
// Fixed-length mode (no padding)
global RATE: u32 = 3;
global TWO_POW_64: Field = 18446744073709551616;

global MAX_BATCH: u32 = 1;

// Domain tags
global D_IDENT: Field = 2;
global D_PAY: Field = 3;
global D_NULL: Field = 4;

fn poseidon2_sponge_hash<let N: u32>(inputs: [Field; N]) -> Field {
    let iv: Field = (N as Field) * TWO_POW_64;
    let mut state: [Field; 4] = [0, 0, 0, iv];
    let mut cache: [Field; 3] = [0; 3];
    let mut cache_size: u32 = 0;

    for i in 0..N {
        if cache_size == RATE {
            // perform duplex: add cache to state, permute
            for j in 0..RATE {
                state[j] += cache[j];
            }
            state = poseidon2_permutation(state, 4);
            cache[0] = inputs[i];
            cache_size = 1;
        } else {
            cache[cache_size] = inputs[i];
            cache_size += 1;
        }
    }

    // Final squeeze: perform duplex with remaining cache
    for j in 0..RATE {
        if j < cache_size {
            state[j] += cache[j];
        }
    }
    state = poseidon2_permutation(state, 4);

    state[0]
}

fn poseidon2_hash2(a: Field, b: Field) -> Field {
    poseidon2_sponge_hash([a, b])
}

fn poseidon2_hash4(a: Field, b: Field, c: Field, d: Field) -> Field {
    poseidon2_sponge_hash([a, b, c, d])
}

// Compute Merkle root from leaf + index + sibling path
fn compute_merkle_root(leaf: Field, index: Field, path: [Field; 16]) -> Field {
    let mut current = leaf;
    let index_bits: [u1; 16] = index.to_le_bits();
    for i in 0..16 {
        if index_bits[i] == 0 {
            current = poseidon2_hash2(current, path[i]);
        } else {
            current = poseidon2_hash2(path[i], current);
        }
    }
    current
}

fn main(
    // Private
    claiming_keys: [Field; MAX_BATCH],
    nonces: [Field; MAX_BATCH],
    amounts: [Field; MAX_BATCH],
    leaf_indices: [Field; MAX_BATCH],
    merkle_paths: [[Field; 16]; MAX_BATCH],
    // Public
    chain_id: pub Field,
    merkle_root: pub Field,
    nullifiers: pub [Field; MAX_BATCH],
    receiving_address: pub Field,
    token_address: pub Field,
    total_amount: pub Field,
    actual_count: pub Field,
) {
    // 1. actual_count >= 1 and actual_count <= MAX_BATCH
    assert(actual_count as u32 >= 1, "actual_count must be >= 1");
    assert(actual_count as u32 <= MAX_BATCH, "actual_count must be <= MAX_BATCH");

    let mut computed_total: Field = 0;

    for i in 0..MAX_BATCH {
        if (i as u64) < (actual_count as u64) {
            // Active slot: validate and accumulate
            let leaf_index = leaf_indices[i];
            let claiming_key = claiming_keys[i];
            let nonce = nonces[i];
            let amount = amounts[i];

            // Range check: leaf_index < 2^16
            let _: [u1; 16] = leaf_index.to_le_bits();

            // Range check: amount < 2^128
            let _: [u1; 128] = amount.to_le_bits();

            // receiverCommitment = poseidon2(claimingKey, receivingAddress)
            let receiver_commitment = poseidon2_sponge_hash([D_IDENT, claiming_key, receiving_address]);

            // paymentCommitment = poseidon2(receiverCommitment, tokenAddress, amount, nonce)
            let payment_commitment = poseidon2_sponge_hash([D_PAY, chain_id, receiver_commitment, token_address, amount, nonce]);

            // Merkle proof
            let computed_root = compute_merkle_root(payment_commitment, leaf_index, merkle_paths[i]);
            assert(computed_root == merkle_root, "invalid merkle proof");

            // nullifier must not be zero
            assert(nullifiers[i] != 0, "nullifier must not be zero");

            // nullifier = poseidon2(claimingKey, tokenAddress, amount, nonce)
            let computed_nullifier = poseidon2_sponge_hash([D_NULL, chain_id, claiming_key, token_address, amount, nonce]);
            assert(computed_nullifier == nullifiers[i], "invalid nullifier");

            // Accumulate total
            computed_total += amount;
        } else {
            // Padding slot: nullifier must be zero
            assert(nullifiers[i] == 0, "padding nullifier must be zero");
        }
    }

    // 4. computed_total == total_amount
    assert(computed_total == total_amount, "total_amount mismatch");

    // No nullifier uniqueness check -- by design. Double-spend protection is provided
    // by the contract's global _nullifierUsed mapping, not the circuit.
}

// --- Tests ---

#[test]
fn test_poseidon2_alignment() {
    let h = poseidon2_hash2(1, 2);
    let expected = 0x038682aa1cb5ae4e0a3f13da432a95c77c5c111f6f030faf9cad641ce1ed7383;
    assert(h == expected, "hash2(1,2) mismatch with bb.js");
}

#[test]
fn test_poseidon2_hash4_alignment() {
    let h = poseidon2_hash4(1, 2, 3, 4);
    let expected = 0x130bf204a32cac1f0ace56c78b731aa3809f06df2731ebcf6b3464a15788b1b9;
    assert(h == expected, "hash4(1,2,3,4) mismatch with bb.js");
}

#[test]
fn test_poseidon2_hash2_zeros() {
    let h = poseidon2_hash2(0, 0);
    let expected = 0x0b63a53787021a4a962a452c2921b3663aff1ffd8d5510540f8e659e782956f1;
    assert(h == expected, "hash2(0,0) mismatch with bb.js");
}

#[test(should_fail_with = "nullifier must not be zero")]
fn test_rejects_zero_nullifier() {
    let claiming_key: Field = 123;
    let receiving_address: Field = 456;
    let token_address: Field = 789;
    let amount: Field = 1000;
    let nonce: Field = 42;

    let chain_id: Field = 1;
    let rc = poseidon2_sponge_hash([D_IDENT, claiming_key, receiving_address]);
    let leaf = poseidon2_sponge_hash([D_PAY, chain_id, rc, token_address, amount, nonce]);

    let leaf_index: Field = 0;
    let merkle_path: [Field; 16] = [0; 16];

    let mut expected_root = leaf;
    for _i in 0..16 {
        expected_root = poseidon2_hash2(expected_root, 0);
    }

    // Pass zero nullifier - should fail
    main(
        [claiming_key],
        [nonce],
        [amount],
        [leaf_index],
        [merkle_path],
        chain_id,
        expected_root,
        [0], // zero nullifier
        receiving_address,
        token_address,
        amount,
        1,
    );
}

