#[test]
fn test_batch1_valid() {
    let claiming_key: Field = 123;
    let receiving_address: Field = 456;
    let token_address: Field = 789;
    let amount: Field = 1000;
    let nonce: Field = 42;

    let chain_id: Field = 1;

    // Compute receiver commitment
    let rc = poseidon2_sponge_hash([D_IDENT, claiming_key, receiving_address]);

    // Compute payment commitment (this is the leaf)
    let leaf = poseidon2_sponge_hash([D_PAY, chain_id, rc, token_address, amount, nonce]);

    // Build a 1-leaf merkle tree at index 0
    // All siblings are 0 (sparse tree)
    let leaf_index: Field = 0;
    let merkle_path: [Field; 16] = [0; 16];

    // Compute expected root by hashing up from leaf at index 0
    // At each level, leaf is on the left (index bit = 0), sibling is 0
    let mut expected_root = leaf;
    for _i in 0..16 {
        expected_root = poseidon2_hash2(expected_root, 0);
    }

    // Compute nullifier
    let nullifier = poseidon2_sponge_hash([D_NULL, chain_id, claiming_key, token_address, amount, nonce]);

    // Call main
    main(
        [claiming_key],
        [nonce],
        [amount],
        [leaf_index],
        [merkle_path],
        chain_id,
        expected_root,
        [nullifier],
        receiving_address,
        token_address,
        amount,
        1,
    );
}
